// canonCatch runs f and returns its result, or the code of the *rt.EvalError it
// panicked with. Any other panic is re-raised.
func canonCatch[T any](f func() T) (got T, code string) {
	defer func() {
		if r := recover(); r != nil {
			e, ok := r.(*rt.EvalError)
			if !ok {
				panic(r)
			}
			code = e.Code
		}
	}()
	return f(), ""
}

func canonShow[T any](v T, ok bool) string {
	if !ok {
		return "none"
	}
	return fmt.Sprint(v)
}

func TestIncrConformance(t *testing.T) {
	vectors := []struct {
		x    int64
		want int64
		code string // expected error code; empty when want is expected
	}{
		{1, 2, ""},
		{math.MaxInt64, 0, "E4101"},
	}
	for _, v := range vectors {
		got, code := canonCatch(func() int64 { return Incr(v.x) })
		if code != v.code || (v.code == "" && got != v.want) {
			t.Errorf("incr(x=%d) = %d [%s], canon says %d [%s]",
				v.x, got, code, v.want, v.code)
		}
	}
}

